using System;
using System.IO;
using System.Linq;
namespace JingFamily {
 public static class WorkshopTests {
  public static int Run(string dir){int count=0;Action<bool,string> check=(ok,label)=>{if(!ok)throw new Exception("Workshop test: "+label);count++;};Action<Action,string> reject=(a,label)=>{bool caught=false;try{a();}catch{caught=true;}check(caught,label);};
   Store.Data=Store.Sample();Store.Save();var root=Store.Data.People[0];int start=Store.Data.People.Count;var added=Workshop.AddRelative(root.Id,"儿子","新增子女","1970","未知",true);check(added.People.Last().FatherId==root.Id&&Store.Data.People.Count==start,"relative staging");check(added.People.Last().Gender=="男","son gender");reject(()=>Workshop.AddRelative(Store.Data.People[2].Id,"父亲","重复父亲","1940","男",true),"existing parent protected");var sibling=Workshop.AddRelative(Store.Data.People[2].Id,"姐妹","新姐妹","1970","女",false).People.Last();check(sibling.FatherId==root.Id&&sibling.MotherId==Store.Data.People[1].Id,"sibling parents");var spouse=Workshop.AddRelative(Store.Data.People[6].Id,"配偶","新配偶","1999","男",true);check(spouse.People.Last().Spouses.Contains(Store.Data.People[6].Id)&&spouse.People[6].Spouses.Contains(spouse.People.Last().Id),"quick spouse symmetry");
   var bulk=Workshop.Bulk(new[]{root.Id},"Generation","新字辈",false);check(bulk.People[0].Generation==root.Generation,"bulk default protects existing");bulk=Workshop.Bulk(new[]{root.Id},"Generation","新字辈",true);check(bulk.People[0].Generation=="新字辈"&&Store.Data.People[0].Generation=="明","bulk overwrite staging");reject(()=>Workshop.Bulk(new string[0],"Place","苏州",false),"bulk selection required");
   check(Workshop.NextDate("2000-02-29",new DateTime(2027,2,1))==new DateTime(2027,2,28),"leap reminder");check(Workshop.NextDate("2000-02-29",new DateTime(2027,3,1))==new DateTime(2028,2,29),"next leap reminder");var calendar=Workshop.Reminders(Store.Data,new DateTime(2026,10,1),30);check(calendar.Any(x=>x.Kind=="忌日"&&x.PersonId==root.Id&&x.Years==8),"death anniversary");check(!calendar.Any(x=>x.Kind=="生日"&&x.PersonId==root.Id),"deceased birthday excluded");check(Workshop.Review(Store.Data,true).Any(),"missing field audit");var old=Workshop.Clone();old.People[2].Birth="1940";check(Workshop.Review(old,false).Any(x=>x.PersonId==old.People[2].Id),"parent age audit");
   string source=Path.Combine(dir,"merge-portrait.txt");File.WriteAllText(source,"test portrait bytes");string file=Store.AddMedia(source);var duplicate=new Person{Name=root.Name,Birth="1938",Phone="123456",Place="不同籍贯",Portrait=file,Biography="另一份生平"};Store.Data.People.Add(duplicate);Store.Data.Events.Add(new FamilyEvent{Title="关联事件",PersonId=duplicate.Id});Store.Data.Documents.Add(new Document{Title="文档",File=file,PersonId=duplicate.Id});Store.Data.Tasks.Add(new ResearchTask{Title="采访长辈",PersonId=duplicate.Id,Due="2026-12-01"});Store.Save();check(Workshop.Duplicates(Store.Data).Count()==1,"duplicate grouping");string summary;var merged=Workshop.Merge(root.Id,duplicate.Id,out summary);check(merged.People.Count==start,"merge count");check(merged.People[0].Phone=="123456"&&merged.People[0].Biography.Contains("不同籍贯"),"merge fill and conflicts");check(merged.Events.Last().PersonId==root.Id&&merged.Documents.Last().PersonId==root.Id&&merged.Tasks[0].PersonId==root.Id,"merge all references");check(merged.People[0].Portrait==file,"merge portrait");reject(()=>Workshop.Merge(root.Id,Store.Data.People[2].Id,out summary),"ancestor merge blocked");reject(()=>Workshop.Merge(root.Id,Store.Data.People[1].Id,out summary),"spouse merge blocked");check(Store.Data.People.Count==start+1,"merge does not mutate until saved");Store.Replace(merged,null);check(Directory.GetFiles(Path.Combine(Store.Root,"backups"),"*.zip").Length>0,"merge backed up");
   string xlsx=Path.Combine(dir,"editable.xlsx");Templates.ExportEditable(xlsx);var batch=Templates.Read(xlsx);check(batch.Data.People.Count==Store.Data.People.Count,"editable export count");var edit=batch.Data.People.Find(x=>batch.SourceIds[x.Id]==root.Id);edit.Occupation="表格回填职业";edit.Phone="";var update=batch.CombineUpdate();var p=update.People.Find(x=>x.Id==root.Id);check(p.Occupation=="表格回填职业"&&p.Phone=="","update edited and cleared fields");check(p.Portrait==file&&update.Tasks[0].PersonId==root.Id,"update preserves portrait and tasks");check(update.Events.Last().PersonId==root.Id&&update.Documents.Last().File==file,"update preserves events attachments");check(Store.Get(root.Id).Occupation=="教师","update staging");var unknown=Templates.ReadRows(Templates.ParseCsv("编号,姓名\r\nNOT-EXIST,甲"),"unknown");reject(()=>unknown.CombineUpdate(),"update unknown IDs rejected");Store.Replace(update,null);Store.Load();check(Store.Get(root.Id).Occupation=="表格回填职业"&&Store.Data.Tasks.Count==1,"update persistence");
   var restored=Workshop.Previous();check(restored.People.Find(x=>x.Id==root.Id).Occupation=="教师","previous saved version");var invalid=Workshop.Clone();invalid.Tasks[0].Due="2026";reject(()=>Store.Commit(invalid),"task full date required");check(Store.Data.Tasks[0].Due=="2026-12-01","invalid commit does not mutate");var migrated=Store.Sample();migrated.Version=1;Store.Validate(migrated);check(migrated.Version==2&&migrated.Tasks.Count==0,"old schema migration");Store.DeletePerson(root.Id);check(Store.Data.Tasks[0].PersonId=="","delete clears task association");
   using(var panel=new WorkbenchPanel(id=>{})){panel.Size=new System.Drawing.Size(1100,650);panel.CreateControl();panel.PerformLayout();using(var bitmap=new System.Drawing.Bitmap(panel.Width,panel.Height)){panel.DrawToBitmap(bitmap,new System.Drawing.Rectangle(0,0,panel.Width,panel.Height));bitmap.Save(Path.Combine(dir,"Workbench-panel-preview.png"));}count++;}using(var win=new BulkEditor()){win.CreateControl();count++;}using(var win=new MergeWindow()){win.CreateControl();count++;}using(var win=new TaskEditor(null)){win.CreateControl();count++;}using(var win=new QuickRelativeEditor(Store.Data.People[0].Id)){win.CreateControl();count++;}
   using(var win=new MainWindow()){typeof(MainWindow).GetMethod("Navigate",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).Invoke(win,new object[]{"编修工作台"});win.CreateControl();win.PerformLayout();using(var bitmap=new System.Drawing.Bitmap(win.Width,win.Height)){win.DrawToBitmap(bitmap,new System.Drawing.Rectangle(0,0,win.Width,win.Height));bitmap.Save(Path.Combine(dir,"Workbench-preview.png"));}count++;}return count;
  }
 }
}
